        queue = [(start, [start])]
        visited = set()

        while queue:
            (vertex, path) = queue.pop(0)
            if vertex not in visited:
                for neighbor in graph[vertex]:
                    if neighbor == goal:
                        return len(path), path + [neighbor]
                    elif neighbor not in visited:
                        queue.append((neighbor, path + [neighbor]))
                visited.add(vertex)

