                    steps = bfs_with_added_word(start_word, end_word, new_word, {start_word})
                    if steps < min_steps:
                        min_steps = steps
                        best_word = new_word
    if min_steps == float('inf'):
        return "0", "-1"
    elif min_steps > len(dictionary) + 1:
        return "0", "0"
    else:
        return best_word, str(min_steps)

