import sys

def find_min_word_to_add(start, end, dictionary):
    def is_valid_word(word, dict_set):
        return word in dict_set

    def generate_neighbors(word, dict_set):
        neighbors = []
        for i in range(len(word)):
            for char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                if char != word[i]:
                    new_word = word[:i] + char + word[i+1:]
                    if is_valid_word(new_word, dict_set):
                        neighbors.append(new_word)
        return neighbors

    from collections import deque

    queue = deque([(start, 1)])
    visited = set([start])
    dict_set = set(dictionary)

    while queue:
        current, steps = queue.popleft()

        if current == end:
            return current, steps

        for neighbor in generate_neighbors(current, dict_set):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, steps + 1))

    return None, -1

