    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    dictionary = data[1:n+1]
    start = dictionary[0]
    end = dictionary[1]

    result_word, result_steps = find_min_word_to_add(start, end, dictionary)

    if result_word:
